var D=[{"id": "real-estate", "name": "Real Estate", "tag": "Sell More. Grow Faster.", "title": "Get Premium Leads with <em>Meta Ads</em>", "pts": ["More Property Enquiries", "Qualified Buyers", "Higher Bookings"], "img": "data:image/jpeg;base64,"}, {"id": "interior-designers", "name": "Interior Designers", "tag": "Turn Ideas into Clients", "title": "Get More Leads with <em>Meta Ads</em>", "pts": ["Showcase Your Work", "Get High-Quality Clients", "Grow Your Brand"], "img": "data:image/jpeg;base64,"}, {"id": "coaching-institutes", "name": "Coaching Institutes", "tag": "Fill Your Seats", "title": "Get More Admissions with <em>Meta Ads</em>", "pts": ["Attract New Students", "Increase Enquiries", "Grow Your Institute"], "img": "data:image/jpeg;base64,"}, {"id": "ielts-immigration", "name": "IELTS &amp; Immigration", "tag": "Your Global Future", "title": "Get More Students with <em>Meta Ads</em>", "pts": ["Increase Enquiries", "Get More Registrations", "Grow Your Consultancy"], "img": "data:image/jpeg;base64,"}, {"id": "banquet-halls", "name": "Banquet Halls", "tag": "Make Every Event Special", "title": "Get More Bookings with <em>Meta Ads</em>", "pts": ["Wedding &amp; Event Leads", "Higher Bookings", "Grow Your Business"], "img": "data:image/jpeg;base64,"}, {"id": "solar-companies", "name": "Solar Companies", "tag": "Go Green, Grow Business", "title": "Get More Customers with <em>Meta Ads</em>", "pts": ["Generate Quality Leads", "Increase Sales", "Grow Your Brand"], "img": "data:image/jpeg;base64,"}, {"id": "dental-clinics", "name": "Dental Clinics", "tag": "Healthy Smiles, More Patients", "title": "Get More Appointments with <em>Meta Ads</em>", "pts": ["Attract New Patients", "Grow Your Clinic", "Increase Bookings"], "img": "data:image/jpeg;base64,"}, {"id": "wedding-planners", "name": "Wedding Planners", "tag": "Plan. Celebrate. Grow.", "title": "Get More Clients with <em>Meta Ads</em>", "pts": ["More Wedding Enquiries", "Premium Clients", "Grow Your Business"], "img": "data:image/jpeg;base64,"}, {"id": "hotels-resorts", "name": "Hotels &amp; Resorts", "tag": "Welcome More Guests", "title": "Get More Bookings with <em>Meta Ads</em>", "pts": ["Increase Room Bookings", "Boost Direct Sales", "Grow Your Brand"], "img": "data:image/jpeg;base64,"}, {"id": "modular-kitchens", "name": "Modular Kitchens", "tag": "Design Better. Sell More.", "title": "Get More Leads with <em>Meta Ads</em>", "pts": ["Get Kitchen Enquiries", "Increase Orders", "Grow Your Business"], "img": "data:image/jpeg;base64,"}, {"id": "gyms-fitness", "name": "Gyms &amp; Fitness Centres", "tag": "Get Fit. Grow Stronger.", "title": "Get More Members with <em>Meta Ads</em>", "pts": ["Increase Memberships", "Fill Your Gym", "Grow Your Fitness Brand"], "img": "data:image/jpeg;base64,"}, {"id": "car-dealerships", "name": "Car Dealerships", "tag": "Drive More Sales", "title": "Get More Test Drives with <em>Meta Ads</em>", "pts": ["Increase Enquiries", "Boost Sales", "Grow Your Dealership"], "img": "data:image/jpeg;base64,"}];
var WA=GH.waLink("Hi GH Company, I would like a free Meta Ads consultation.");
var app=document.getElementById('app');
function head(){return '<div class="brand">GH Company<i></i>META ADS EXPERTS</div>';}
function home(){
  var h=head()+'<a class="back" href="../index.html">\u2190 BACK TO OUR WORK</a><h1>Meta Ads that <em>fill</em> your business.</h1><p class="lead">Pick your industry to see how we generate quality leads on Facebook and Instagram.</p><div class="grid">';
  D.forEach(function(d){h+='<a class="card" href="#'+d.id+'"><img src="'+d.img+'" alt="'+d.name+' Meta Ads poster" loading="lazy"><span>'+d.name+'<b>\u2192</b></span></a>';});
  app.innerHTML=h+'</div>'+consult('')+foot()+'';
}
function page(d){
  var li=d.pts.map(function(p){return '<li>'+p+'</li>';}).join('');
  var ch=D.filter(function(x){return x.id!==d.id;}).map(function(x){return '<a href="#'+x.id+'">'+x.name+'</a>';}).join('');
  app.innerHTML=head()+'<a class="back" href="#home">\u2190 ALL INDUSTRIES</a><div class="detail"><img src="'+d.img+'" alt="'+d.name+' Meta Ads poster"><div><div class="tag">'+d.tag.toUpperCase()+'</div><h2>'+d.title+'</h2><ul>'+li+'</ul><button class="cta" type="button" data-scroll>BOOK A FREE CONSULTATION \u2192</button><a class="cta ghost" href="'+WA+'" target="_blank" rel="noopener">WHATSAPP US</a></div></div><div class="more"><p>MORE INDUSTRIES</p><div class="chips">'+ch+'</div></div>'+consult(d.name)+foot()+'';
}
function route(){
  var id=location.hash.slice(1);
  var d=D.filter(function(x){return x.id===id;})[0];
  if(d){page(d);document.title=d.name+' \u2013 Meta Ads';}else{home();document.title='Meta Ads for Local Businesses \u2013 12 Industries';}
  bindConsult();window.scrollTo(0,0);
}
window.addEventListener('hashchange',route);route();

function foot(){return '<footer>\u00a9 GH Company \u00b7 Rewari, Haryana \u00b7 Run by our digital marketing experts<div class="contact-line"><a href="tel:+917206718075">+91 72067 18075</a> \u00b7 <a href="'+GH.waLink()+'" target="_blank" rel="noopener">WhatsApp</a> \u00b7 <a href="mailto:ghcompanyofficial@gmail.com">ghcompanyofficial@gmail.com</a> \u00b7 <a href="'+GH.insta+'" target="_blank" rel="noopener">Instagram</a></div></footer>';}
function consult(sel){var o=D.map(function(x){return '<option'+(x.name===sel?' selected':'')+'>'+x.name+'</option>';}).join('');
return '<section class="consult" id="consult"><h2>Book a Free <em>Consultation</em></h2><p class="lead">Tell us about your business. GH Company will contact you within 24 hours.</p><form id="ghc" novalidate><label>Your name<input name="name" autocomplete="name"><span class="err"></span></label><label>Mobile number<input name="phone" type="tel" inputmode="numeric" maxlength="10" autocomplete="tel"><span class="err"></span></label><label>Industry<select name="ind">'+o+'</select></label><label>Email (optional)<input name="email" type="email" autocomplete="email"><span class="err"></span></label><label class="full">Message<textarea name="msg" rows="3"></textarea></label><div class="full"><button class="cta" type="submit">SEND ENQUIRY</button></div></form></section>';}
function bindConsult(){var f=document.getElementById('ghc');if(!f)return;GH.prep(f);
document.querySelectorAll('[data-scroll]').forEach(function(b){b.onclick=function(){f.scrollIntoView({behavior:'smooth',block:'start'})}});
f.addEventListener('submit',function(e){e.preventDefault();var v=f.elements,er=f.querySelectorAll('.err'),ok=true;er.forEach(function(x){x.textContent=''});
if(v.name.value.trim().length<2){er[0].textContent='Enter your name';ok=false}
if(!/^[6-9]\d{9}$/.test(v.phone.value.replace(/\D/g,'').slice(-10))){er[1].textContent='Enter a valid 10-digit mobile number';ok=false}
if(v.email.value&&!/^\S+@\S+\.\S+$/.test(v.email.value)){er[2].textContent='Enter a valid email';ok=false}
if(!ok)return;
var m='Hello GH Company, I would like a free Meta Ads consultation.\nName: '+v.name.value+'\nMobile: '+v.phone.value+'\nIndustry: '+v.ind.value+(v.email.value?'\nEmail: '+v.email.value:'')+(v.msg.value?'\nMessage: '+v.msg.value:'');
GH.send(f,'Meta Ads consultation',{name:v.name.value,phone:v.phone.value,email:v.email.value},m)})}
